#!/usr/bin/env python3
"""Generate rtl/input/keymap_decode.v from integration/keymap.csv (single source of truth)."""
import csv
from pathlib import Path

KIND_ENC = {"NOP": 0, "DIGIT": 1, "OP": 2, "CTRL": 3, "MEM": 4}

def main():
    root = Path(__file__).resolve().parent.parent
    csv_path = root / "integration" / "keymap.csv"
    out_path = root / "rtl" / "input" / "keymap_decode.v"

    rows = list(csv.DictReader(csv_path.open(encoding="utf-8")))
    assert len(rows) == 32, f"Expected 32 keys, got {len(rows)}"

    lines = [
        "// AUTO-GENERATED by scripts/gen_keymap.py from integration/keymap.csv",
        "// Do not edit by hand; update integration/keymap.csv and re-run scripts/gen_keymap.py.",
        "// key_kind encoding: 0=NOP, 1=DIGIT, 2=OP, 3=CTRL (1=CLR,2=DEL,3=DOT,4=ENT), 4=MEM (12=STO,13=RCL)",
        "module keymap_decode (",
        "    input      [4:0] key_code,",
        "    output reg [2:0] key_kind,",
        "    output reg [3:0] key_val",
        ");",
        "    always @(*) begin",
        "        key_kind = 3'd0;",
        "        key_val  = 4'd0;",
        "        case (key_code)",
    ]
    for r in sorted(rows, key=lambda x: int(x["key_code"])):
        kc = int(r["key_code"])
        assert kc == (int(r["row"]) << 3) | int(r["col"]), f"key_code mismatch on {r['key_ref']}"
        kenc = KIND_ENC[r["kind"]]
        val = int(r["code_val"])
        lines.append(
            f"            5'd{kc:<2d}: begin key_kind = 3'd{kenc}; key_val = 4'd{val:<2d}; end // {r['key_ref']} ({r['legend']})"
        )
    lines += [
        "            default: begin key_kind = 3'd0; key_val = 4'd0; end",
        "        endcase",
        "    end",
        "endmodule",
        "",
    ]
    out_path.write_text("\n".join(lines), encoding="utf-8")
    print(f"Generated {out_path} ({len(rows)} keys)")

if __name__ == "__main__":
    main()
